 "content": "from collections import deque


def transform(grid):
    """Fill the interiors of hollow rectangular frames.

    A one-cell cavity is marked 7; larger cavities are filled with 2,
    matching the demonstrated size-dependent fill convention.
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if seen[r][c] or color == grid[0][0]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            r0 = min(y for y, _ in cells)
            r1 = max(y for y, _ in cells)
            c0 = min(x for _, x in cells)
            c1 = max(x for _, x in cells)
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue
            border = all(
                grid[y][x] == color
                for y in range(r0, r1 + 1)
                for x in range(c0, c1 + 1)
                if y in (r0, r1) or x in (c0, c1)
            )
            interior = [(y, x) for y in range(r0 + 1, r1) for x in range(c0 + 1, c1)]
            if border and all(grid[y][x] == grid[0][0] for y, x in interior):
                fill = 7 if len(interior) == 1 else 2
                for y, x in interior:
                    out[y][x] = fill
    return out


